/* direct mapping table lookup: cost rises roughly with footprint */
let cost=0;
for(let i=0;i<n;i++) cost += (0.02 + 0.00002*n);
return cost;

/* two-level walk: logarithmic structure with slight overhead from footprint */
let levels = Math.log2(n+1);
let overhead = 0.9 + 0.00001*n;
return 2*levels*overhead;

/* inverted map benefits from sparsity but requires index maintenance */
let build = 0.03*n*Math.log2(n+1);
let maintenance = 0.4*Math.sqrt(n);
return build + maintenance;

/* hash directory: average lookup ~log^2 due to collision patterns & rehash costs */
let m = Math.log2(n+1);
let overhead = 0.25 + 0.00005*n;
return overhead * (m*m);

/* radix walk: sublinear trie traversal with linear fallback for dense regions */
let trie = 0.15*Math.pow(n,0.5);
let dense = 0.02*n;
let guide = 1.1*Math.log2(n+1);
return trie + dense + guide;
